from email_normalize import identity_key, normalize_registration_email
from webinar_models import CanonicalAttendee, LiveJoinEvent, RegistrantImportRow


def _join_event_identity_key(event: LiveJoinEvent) -> str:
    """Map a live join row onto storage — must match imports that share the email."""

    wid = event.webinar_id.strip()
    norm = normalize_registration_email(event.email)
    # Starter bug: treats each join path as a different person, so two links for the same AE duplicate.
    path = event.join_path.strip()
    return f"{wid}::{path}::{norm}"


class WebinarAttendanceLedger:
    """In-memory merge of registrar CSV rows and join callbacks."""

    def __init__(self) -> None:
        self._records: dict[str, CanonicalAttendee] = {}
        self.import_events: int = 0
        self.join_events: int = 0

    def record_import_row(self, row: RegistrantImportRow) -> None:
        key = identity_key(row.webinar_id, row.email)
        self.import_events += 1
        attendee = self._records.get(key)
        norm = normalize_registration_email(row.email)
        if attendee is None:
            attendee = CanonicalAttendee(
                key=key,
                webinar_id=row.webinar_id.strip(),
                normalized_email=norm,
            )
            self._records[key] = attendee
        attendee.touch_import(row.registrant_id, row.registered_at)

    def record_join_event(self, event: LiveJoinEvent) -> None:
        key = _join_event_identity_key(event)
        self.join_events += 1
        norm = normalize_registration_email(event.email)
        attendee = self._records.get(key)
        if attendee is None:
            attendee = CanonicalAttendee(
                key=key,
                webinar_id=event.webinar_id.strip(),
                normalized_email=norm,
            )
            self._records[key] = attendee
        attendee.note_join_path(event.join_path)
        attendee.bump_live_join()

    def canonical_attendees(self) -> list[CanonicalAttendee]:
        return sort_attendees_internal(list(self._records.values()))

    def unique_people(self) -> int:
        return len(self._records)


