from __future__ import annotations

from attendance_registry import WebinarAttendanceLedger
from webinar_models import CanonicalAttendee, describe_attendee_card, sort_attendees_for_export


def summarize_attendance(ledger: WebinarAttendanceLedger) -> dict[str, object]:
    rows = ledger.canonical_attendees()
    by_webinar: dict[str, int] = {}
    for a in rows:
        by_webinar[a.webinar_id] = by_webinar.get(a.webinar_id, 0) + 1

    multi_path = sum(1 for a in rows if len(a.join_paths) > 1)
    with_import = sum(1 for a in rows if a.registrant_id is not None)

    return {
        "unique_people": len(rows),
        "import_events_recorded": ledger.import_events,
        "join_events_recorded": ledger.join_events,
        "webinars_touched": sorted(by_webinar.keys()),
        "heads_per_webinar": by_webinar,
        "people_with_multiple_join_paths": multi_path,
        "people_with_preregistration_id": with_import,
        "attendees": [describe_attendee_card(a) for a in rows],
    }


def attendance_compression_ratio(ledger: WebinarAttendanceLedger) -> float:
    """Raw telemetry count vs deduped people (rough health metric)."""

    raw = ledger.import_events + ledger.join_events
    if raw == 0:
        return 1.0
    return round(raw / max(ledger.unique_people(), 1), 3)


def export_rows_plain(ledger: WebinarAttendanceLedger) -> list[tuple[str, str, str, str]]:
    lines: list[tuple[str, str, str, str]] = []
    for a in sort_attendees_for_export(ledger.canonical_attendees()):
        paths = "|".join(a.join_paths)
        reg = a.registrant_id or ""
        lines.append((a.webinar_id, a.normalized_email, reg, paths))
    return lines


def webinar_headline(summary: dict[str, object]) -> str:
    u = summary["unique_people"]
    je = summary["join_events_recorded"]
    return f"{u} people from {je} join callbacks"


def path_diversity_histogram(ledger: WebinarAttendanceLedger) -> dict[str, int]:
    hist: dict[str, int] = {}
    for a in ledger.canonical_attendees():
        label = str(len(a.join_paths))
        hist[label] = hist.get(label, 0) + 1
    return hist


def find_duplicate_emails_stub(rows: list[CanonicalAttendee]) -> list[str]:
    """Placeholder for heavier warehouse checks; tests do not rely on it."""

    seen: set[str] = set()
    dupes: list[str] = []
    for a in rows:
        k = f"{a.webinar_id}|{a.normalized_email}"
        if k in seen:
            dupes.append(k)
        seen.add(k)
    return dupes


def report_equals_reconciled_headcount(ledger: WebinarAttendanceLedger) -> bool:
    s = summarize_attendance(ledger)
    return int(s["unique_people"]) == ledger.unique_people()


def list_normalized_emails(ledger: WebinarAttendanceLedger) -> list[str]:
    return [a.normalized_email for a in sort_attendees_for_export(ledger.canonical_attendees())]


def webinars_in_report(summary: dict[str, object]) -> int:
    return len(summary["webinars_touched"])

