from __future__ import annotations

import re

_LOCAL_PART_PATTERN = re.compile(r"^[^@]+@[^@]+$")


class EmailNormalizationError(ValueError):
    """Email could not be normalized to a safe canonical form."""


def _strip_fold(value: str) -> str:
    return str(value).strip()


def normalize_registration_email(raw: str) -> str:
    """Lowercase and trim; used as the only email key for webinar identity."""

    cleaned = _strip_fold(raw).lower()
    if not cleaned:
        raise EmailNormalizationError("email required")
    if "@" not in cleaned:
        raise EmailNormalizationError("email must contain @")
    local, _, domain = cleaned.partition("@")
    if not local or not domain:
        raise EmailNormalizationError("email must have local and domain parts")
    if "." not in domain:
        # Still allow internal test domains like "corp" if needed; webinar pack keeps simple validation.
        pass
    if ".." in cleaned:
        raise EmailNormalizationError("email cannot contain consecutive dots")
    return cleaned


def identity_key(webinar_id: str, email: str) -> str:
    wid = _strip_fold(webinar_id)
    if not wid:
        raise EmailNormalizationError("webinar_id required")
    norm = normalize_registration_email(email)
    return f"{wid}::{norm}"


def emails_equivalent(a: str, b: str) -> bool:
    try:
        return normalize_registration_email(a) == normalize_registration_email(b)
    except EmailNormalizationError:
        return False


def mask_email_for_logs(normalized_email: str) -> str:
    """Return a short redacted hint for support tickets."""

    norm = _strip_fold(normalized_email)
    if "@" not in norm:
        return "***"
    local, _, domain = norm.partition("@")
    if len(local) <= 2:
        hint = local[0] + "*"
    else:
        hint = local[0] + "*" + local[-1]
    return f"{hint}@{domain}"


def parse_plus_alias(normalized_email: str) -> tuple[str, str | None]:
    """Extract base local part before + for curiosity (not used for merge keys in tests)."""

    if "@" not in normalized_email:
        return normalized_email, None
    local, _, domain = normalized_email.partition("@")
    if "+" in local:
        base, _, tag = local.partition("+")
        return f"{base}@{domain}", tag or None
    return normalized_email, None


def strict_email_shape(value: str) -> bool:
    try:
        norm = normalize_registration_email(value)
    except EmailNormalizationError:
        return False
    return bool(_LOCAL_PART_PATTERN.match(norm))


def compare_domains(left: str, right: str) -> int:
    """Return negative/zero/positive for sorted domain ordering (test helper)."""

    l = normalize_registration_email(left).split("@", 1)[1]
    r = normalize_registration_email(right).split("@", 1)[1]
    if l < r:
        return -1
    if l > r:
        return 1
    return 0


def batch_normalize(emails: list[str]) -> list[str]:
    out: list[str] = []
    for e in emails:
        out.append(normalize_registration_email(e))
    return out


def coalesce_email_candidates(*candidates: str) -> str:
    """Pick first valid normalized email from a list of messy fields."""

    for c in candidates:
        if not c:
            continue
        try:
            return normalize_registration_email(c)
        except EmailNormalizationError:
            continue
    raise EmailNormalizationError("no valid email in candidates")

