from dataclasses import dataclass, field

from email_normalize import EmailNormalizationError, normalize_registration_email


@dataclass(frozen=True)
class RegistrantImportRow:
    webinar_id: str
    email: str
    registrant_id: str
    registered_at: str

    def __post_init__(self) -> None:
        wid = str(self.webinar_id).strip()
        if not wid:
            raise EmailNormalizationError("webinar_id required")
        rid = str(self.registrant_id).strip()
        if not rid:
            raise EmailNormalizationError("registrant_id required")
        ts = str(self.registered_at).strip()
        if not ts:
            raise EmailNormalizationError("registered_at required")
        normalize_registration_email(self.email)
        object.__setattr__(self, "webinar_id", wid)
        object.__setattr__(self, "registrant_id", rid)
        object.__setattr__(self, "registered_at", ts)


@dataclass(frozen=True)
class LiveJoinEvent:
    webinar_id: str
    email: str
    join_path: str
    joined_at: str

    def __post_init__(self) -> None:
        wid = str(self.webinar_id).strip()
        if not wid:
            raise EmailNormalizationError("webinar_id required")
        jp = str(self.join_path).strip()
        if not jp:
            raise EmailNormalizationError("join_path required")
        ts = str(self.joined_at).strip()
        if not ts:
            raise EmailNormalizationError("joined_at required")
        normalize_registration_email(self.email)
        object.__setattr__(self, "webinar_id", wid)
        object.__setattr__(self, "join_path", jp)
        object.__setattr__(self, "joined_at", ts)


@dataclass
class CanonicalAttendee:
    """Aggregated attendance for one email in one webinar."""

    key: str
    webinar_id: str
    normalized_email: str
    registrant_id: str | None = None
    import_registered_at: str | None = None
    join_paths: list[str] = field(default_factory=list)
    join_event_count: int = 0

    def note_join_path(self, path: str) -> None:
        if path not in self.join_paths:
            self.join_paths.append(path)

    def touch_import(self, registrant_id: str, registered_at: str) -> None:
        self.registrant_id = registrant_id
        self.import_registered_at = registered_at

    def bump_live_join(self) -> None:
        self.join_event_count += 1


def import_row_fingerprint(row: RegistrantImportRow) -> str:
    return f"{row.webinar_id}:{row.registrant_id}"


def join_event_fingerprint(event: LiveJoinEvent) -> str:
    return f"{event.webinar_id}:{event.join_path}:{event.joined_at}"


def describe_attendee_card(attendee: CanonicalAttendee) -> str:
    paths = ",".join(attendee.join_paths) if attendee.join_paths else "-"
    reg = attendee.registrant_id or "none"
    return f"{attendee.normalized_email}|reg={reg}|paths={paths}|joins={attendee.join_event_count}"


def sort_attendees_for_export(rows: list[CanonicalAttendee]) -> list[CanonicalAttendee]:
    return sorted(rows, key=lambda r: (r.webinar_id, r.normalized_email))


def webinar_id_set(rows: list[RegistrantImportRow | LiveJoinEvent]) -> set[str]:
    out: set[str] = set()
    for r in rows:
        out.add(str(getattr(r, "webinar_id")).strip())
    return out

