        self.join_event_count += 1


def import_row_fingerprint(row: RegistrantImportRow) -> str:
    return f"{row.webinar_id}:{row.registrant_id}"


def join_event_fingerprint(event: LiveJoinEvent) -> str:
    return f"{event.webinar_id}:{event.join_path}:{event.joined_at}"


def describe_attendee_card(attendee: CanonicalAttendee) -> str:
    paths = ",".join(attendee.join_paths) if attendee.join_paths else "-"
    reg = attendee.registrant_id or "none"
    return f"{attendee.normalized_email}|reg={reg}|paths={paths}|joins={attendee.join_event_count}"


def sort_attendees_for_export(rows: list[CanonicalAttendee]) -> list[CanonicalAttendee]:
    return sorted(rows, key=lambda r: (r.webinar_id, r.normalized_email))


def webinar_id_set(rows: list[RegistrantImportRow | LiveJoinEvent]) -> set[str]:
    out: set[str] = set()
    for r in rows:
        out.add(str(getattr(r, "webinar_id")).strip())
    return out
